"""Build only owned early-init fixtures and their exact local image profile."""

# Fixed tool paths and owned source/output paths only.
# ruff: noqa: S603
import hashlib
import json
import struct
import subprocess
import tempfile
from pathlib import Path


def array(name: str, data: bytes) -> str:
    """Encode a bounded generated byte array.

    Returns:
        C declaration containing exactly the supplied bytes.
    """
    return f"static const unsigned char {name}[]={{" + ",".join(map(hex, data)) + "};\n"


def main() -> None:
    """Compile the owned executable and minimal C bootstrap, then print the output folder."""
    source = Path(__file__).resolve().parent
    output = Path(tempfile.mkdtemp(prefix="capie-early-patch-"))
    child, later, bootstrap = (
        output / name for name in ("child", "later.dylib", "bootstrap.dylib")
    )
    compiler = [
        "/usr/bin/xcrun",
        "clang",
        "-std=c11",
        "-Wall",
        "-Wextra",
        "-Werror",
        "-Wno-deprecated-declarations",
        "-arch",
        "x86_64",
    ]
    subprocess.run(
        [
            *compiler,
            str(source / "child.c"),
            str(source / "target.s"),
            "-Wl,-export_dynamic",
            "-Wl,-no_adhoc_codesign",
            "-o",
            str(child),
        ],
        check=True,
    )
    subprocess.run(
        [*compiler, "-dynamiclib", str(source / "later.c"), "-o", str(later)], check=True
    )
    listing = subprocess.run(
        ["/usr/bin/nm", "-g", str(child)], capture_output=True, text=True, check=True
    ).stdout
    target = int(
        next(line.split()[0] for line in listing.splitlines() if line.endswith(" _owned_target")),
        16,
    )
    raw = child.read_bytes()
    commands = struct.unpack_from("<I", raw, 20)[0]
    profile = f"#define EXPECTED_TARGET {target:#x}ULL\n"
    profile += "#define EXPECTED_INSERTED " + json.dumps(f"{bootstrap}:{later}") + "\n"
    profile += "#define EXPECTED_LATER " + json.dumps(str(later)) + "\n"
    profile += array("expected_sha", hashlib.sha256(raw).digest())
    profile += array("later_sha", hashlib.sha256(later.read_bytes()).digest())
    profile += array("expected_header", raw[: 32 + commands])
    (output / "profile.h").write_text(profile)
    subprocess.run(
        [
            *compiler,
            "-dynamiclib",
            f"-I{output}",
            str(source / "bootstrap.c"),
            "-o",
            str(bootstrap),
        ],
        check=True,
    )
    print(output)


if __name__ == "__main__":
    main()
